import React from 'react'
import './styles/GroupCard.scss'

const GroupCard = () => {

    const dataCard = ({ data }) => {
        <div className='group-card'>
            {Object.keys(data).map(key => (
                <p key={key}><strong>{key}:</strong> {data[key]}</p>
            ))}
        </div>
    }
  return (
    <div className='group-card-container'>
        
    </div>
  )
}

export default GroupCard
